"use client";

import { useState } from "react";
import Link from "next/link";
import { Eyebrow } from "@/components/ui";

const EMAIL = "hello@npcprotocol.co";

export default function Contact() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [site, setSite] = useState("");
  const [msg, setMsg] = useState("");
  const [sent, setSent] = useState(false);

  function submit(e: React.FormEvent) {
    e.preventDefault();
    const subject = encodeURIComponent(`NPC Protocol — new story (${name || "no name"})`);
    const body = encodeURIComponent(
      `Name: ${name}\nEmail: ${email}\nWebsite: ${site || "(none yet)"}\n\n${msg}`
    );
    window.location.href = `mailto:${EMAIL}?subject=${subject}&body=${body}`;
    setSent(true);
  }

  const inputCls =
    "w-full rounded-xl border border-line bg-ink px-4 py-3 text-sm text-snow placeholder:text-fog-2 outline-none transition-colors focus:border-gold/60 focus:ring-2 focus:ring-gold/20";
  const labelCls = "mb-2 block font-mono text-[11px] uppercase tracking-[0.25em] text-fog";

  return (
    <>
      <section className="relative overflow-hidden border-b border-line bg-grid">
        <div
          className="pointer-events-none absolute left-1/2 top-[-140px] -z-0 h-[420px] w-[720px] -translate-x-1/2 rounded-full blur-[130px]"
          style={{ background: "radial-gradient(circle, var(--color-gold), transparent 70%)", opacity: 0.24 }}
        />
        <div className="relative mx-auto max-w-3xl px-5 py-28 text-center sm:px-8">
          <div className="mb-6 flex justify-center">
            <Eyebrow tone="gold">Start your story</Eyebrow>
          </div>
          <h1 className="font-display text-4xl font-bold leading-[1.05] tracking-tight text-snow sm:text-5xl">
            Tell me what you do. I'll show you the <span className="text-gold text-glow-gold">main character</span> in it.
          </h1>
          <p className="mx-auto mt-6 max-w-xl text-base leading-relaxed text-fog sm:text-lg">
            No pitch decks, no discovery calls that go nowhere. Send a few lines and I'll come back with
            the shape of your story — and a fixed price to build it.
          </p>
        </div>
      </section>

      <section className="relative mx-auto grid max-w-6xl gap-12 px-5 py-24 sm:px-8 lg:grid-cols-[1.4fr_1fr]">
        {/* form */}
        <div className="rounded-3xl border border-line bg-panel p-8 sm:p-10">
          {sent ? (
            <div className="flex flex-col items-start gap-4 py-6">
              <span className="inline-flex items-center gap-2 rounded-full border border-gold/40 bg-gold/10 px-4 py-1.5 font-mono text-[11px] uppercase tracking-[0.25em] text-gold">
                <span className="h-1.5 w-1.5 rounded-full bg-gold" /> Almost there
              </span>
              <h2 className="font-display text-2xl font-bold text-snow">Your email app should be open.</h2>
              <p className="max-w-md text-fog">
                If it didn't, reach me directly at{" "}
                <a href={`mailto:${EMAIL}`} className="text-gold underline underline-offset-4">
                  {EMAIL}
                </a>
                . I read everything myself.
              </p>
              <button
                onClick={() => setSent(false)}
                className="mt-2 text-sm font-medium text-fog underline underline-offset-4 hover:text-snow"
              >
                Write it again
              </button>
            </div>
          ) : (
            <form onSubmit={submit} className="space-y-6">
              <div className="grid gap-6 sm:grid-cols-2">
                <div>
                  <label htmlFor="name" className={labelCls}>
                    Name
                  </label>
                  <input
                    id="name"
                    className={inputCls}
                    placeholder="Alex Rivera"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                  />
                </div>
                <div>
                  <label htmlFor="email" className={labelCls}>
                    Email
                  </label>
                  <input
                    id="email"
                    type="email"
                    required
                    className={inputCls}
                    placeholder="you@company.com"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                  />
                </div>
              </div>
              <div>
                <label htmlFor="site" className={labelCls}>
                  Current website <span className="normal-case tracking-normal text-fog-2">(optional)</span>
                </label>
                <input
                  id="site"
                  className={inputCls}
                  placeholder="https://…"
                  value={site}
                  onChange={(e) => setSite(e.target.value)}
                />
              </div>
              <div>
                <label htmlFor="msg" className={labelCls}>
                  What do you do, and what's wrong with how it's presented?
                </label>
                <textarea
                  id="msg"
                  required
                  rows={5}
                  className={`${inputCls} resize-none`}
                  placeholder="A couple of honest sentences is plenty…"
                  value={msg}
                  onChange={(e) => setMsg(e.target.value)}
                />
              </div>
              <button
                type="submit"
                className="inline-flex w-full items-center justify-center gap-2 rounded-full bg-gold px-6 py-3.5 text-sm font-semibold tracking-wide text-ink shadow-lg shadow-gold/50 transition-all duration-300 hover:-translate-y-0.5 hover:bg-gold-soft"
              >
                Send it <span aria-hidden>→</span>
              </button>
            </form>
          )}
        </div>

        {/* aside */}
        <div className="space-y-5">
          <div className="rounded-3xl border border-line bg-panel p-7">
            <h3 className="font-display text-lg font-semibold text-snow">What happens next</h3>
            <ol className="mt-5 space-y-4">
              {[
                "I read it and reply within a day.",
                "You get the shape of your story + a fixed price.",
                "If it's a fit, we start. Days, not weeks.",
              ].map((t, i) => (
                <li key={t} className="flex items-start gap-3 text-fog">
                  <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-gold/40 font-mono text-[11px] text-gold">
                    {i + 1}
                  </span>
                  <span className="text-sm leading-relaxed">{t}</span>
                </li>
              ))}
            </ol>
          </div>

          <div className="rounded-3xl border border-npc/25 bg-panel p-7">
            <h3 className="font-display text-lg font-semibold text-snow">Prefer email?</h3>
            <p className="mt-3 text-sm leading-relaxed text-fog">
              Skip the form. Write to{" "}
              <a href={`mailto:${EMAIL}`} className="text-npc underline underline-offset-4">
                {EMAIL}
              </a>{" "}
              and I'll take it from there.
            </p>
          </div>

          <div className="rounded-3xl border border-line bg-panel p-7">
            <h3 className="font-display text-lg font-semibold text-snow">Still deciding?</h3>
            <p className="mt-3 text-sm leading-relaxed text-fog">
              Read how it works first —{" "}
              <Link href="/protocol" className="text-gold underline underline-offset-4">
                the Protocol
              </Link>{" "}
              and{" "}
              <Link href="/sarah" className="text-gold underline underline-offset-4">
                Sarah's worked example
              </Link>
              .
            </p>
          </div>
        </div>
      </section>
    </>
  );
}
